update `galaxy_proxy` SET `target_param`='{\r\n    \"query\": \"SELECT app_id AS app_id, app_name AS app_name, app_category AS app_category, app_subcategory AS app_subcategory, app_risk AS app_risk FROM app WHERE 1=1 <#if parameter.appCategory?default(\'\')?trim? length gt 0 > and app_category = \'${parameter.appCategory}\'</#if> <#if parameter.appSubcategory?default(\'\')?trim? length gt 0 > and app_subcategory = \'${parameter.appSubcategory}\'</#if><#if parameter.appRisk?default(\'\')?trim? length gt 0 > and app_risk = \'${parameter.appRisk}\'</#if><#if parameter.appName?default(\'\')?trim? length gt 0 > and app_name = \'${parameter.appName}\'</#if> ORDER BY update_time DESC <#if parameter.pageSize?default(\'\')?trim? length gt 0>limit ${parameter.pageNo},${parameter.pageSize}</#if>\",\r\n    \"option\": \"real-time\",\r\n    \"format\": \"json\"\r\n}' where id = 28;
